#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bascule l'authentification vers des jetons de session temporaires.

A lancer depuis la racine du repo :
    python3 deploy_auth_par_jetons.py
"""
import base64, os

FICHIERS = {
    'models.py': """""",
    'auth.py': """""",
    'api.py': """""",
    'site/admin.html': """""",
    'site/client_upload.html': """""",
    'site/worker_dashboard.html': """""",
    'tests/test_api.py': """""",
}

for chemin, b64 in FICHIERS.items():
    contenu = base64.b64decode(b64).decode('utf-8')
    os.makedirs(os.path.dirname(chemin) or '.', exist_ok=True)
    with open(chemin, 'w', encoding='utf-8') as f:
        f.write(contenu)
    print(f'OK -> {chemin} ({len(contenu)} caracteres)')

print()
print('Termine. Lance ensuite : pytest -q')